(function(){'use strict';
const KEY='nawaf-hq-v5',CFG='nawaf-hq-v15';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const uid=p=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,7);
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason='v15'){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason}}))}
function cfg(){try{return JSON.parse(localStorage.getItem(CFG)||'{}')||{}}catch{return {}}}
function ensure(s){for(const k of ['tasks','reports','activity','projects','employees','approvals','meetings','goals'])if(!Array.isArray(s[k]))s[k]=[];s.projectMemory=s.projectMemory&&typeof s.projectMemory==='object'?s.projectMemory:{};s.permissions=s.permissions&&typeof s.permissions==='object'?s.permissions:{};return s}
function toast(text){let t=$('.v15-toast');if(!t){t=document.createElement('div');t.className='v15-toast';document.body.appendChild(t)}t.textContent=text;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2200)}
function modal(title,html,wide=false){let m=$('#v15-modal');if(!m){m=document.createElement('div');m.id='v15-modal';m.className='v15-modal';m.innerHTML='<div class="v15-dialog"><div class="v15-dialog-head"><div><span>NAWAF HQ</span><h2></h2></div><button data-v15-close>×</button></div><div class="v15-dialog-body"></div></div>';document.body.appendChild(m);m.onclick=e=>{if(e.target===m||e.target.closest('[data-v15-close]'))m.classList.remove('show')}}m.querySelector('h2').textContent=title;m.querySelector('.v15-dialog-body').innerHTML=html;m.querySelector('.v15-dialog').classList.toggle('wide',wide);m.classList.add('show');return m}
function activity(s,text,type='REAL'){s.activity.unshift({id:uid('a'),text,type,at:new Date().toISOString()});s.activity=s.activity.slice(0,180)}
const active=t=>['WORKING','RESEARCHING','REVIEWING'].includes(t.status),open=t=>t.status!=='COMPLETED';
function scoreTask(t){let n=0;if(t.status==='WAITING_FOR_NAWAF')n+=100;if(t.blockedReason)n+=70;if(t.priority==='URGENT')n+=60;else if(t.priority==='HIGH')n+=35;else if(t.priority==='LOW')n-=10;if(active(t))n+=25;const age=Date.parse(t.createdAt||'');if(Number.isFinite(age))n+=Math.min(25,(Date.now()-age)/36e5);return n}
function priorities(s){return [...s.tasks].filter(open).sort((a,b)=>scoreTask(b)-scoreTask(a))}
function load(s,id){return s.tasks.filter(t=>t.employeeId===id&&open(t)).reduce((n,t)=>n+(active(t)?3:1),0)}
function chooseEmployee(s,task){const words=(task.title+' '+(task.details||'')).toLowerCase();const pref=words.match(/جود|اختبر|qa|review/)?/جود|مراجع|quality|نورة/i:words.match(/بحث|تحليل|تقن|كود|برمج/)?/تقن|بحث|مهندس|عمر/i:words.match(/منتج|تجرب|واجهة|تصميم/)?/منتج|تجرب|ليان/i:/مدير|إدارة|سارة/i;return [...s.employees].sort((a,b)=>{const am=pref.test((a.name||'')+' '+(a.role||'')+' '+(a.department||''))?0:10,bm=pref.test((b.name||'')+' '+(b.role||'')+' '+(b.department||''))?0:10;return am+load(s,a.id)-bm-load(s,b.id)})[0]}
function managerRun(){const s=ensure(read());let changed=0;for(const t of priorities(s)){if(!t.employeeId||!s.employees.some(e=>e.id===t.employeeId)){const e=chooseEmployee(s,t);if(e){t.employeeId=e.id;changed++}}if(!t.priority)t.priority=scoreTask(t)>80?'URGENT':scoreTask(t)>45?'HIGH':'NORMAL'}activity(s,`مدير المشاريع AI راجع ${s.tasks.filter(open).length} مهمة وأسند ${changed} مهمة.`);write(s,'v15-manager');toast(changed?`تم إسناد ${changed} مهمة تلقائيًا`:'كل المهام مسندة بالفعل')}
function brief(s){const x={working:s.tasks.filter(active).length,waiting:s.tasks.filter(t=>t.status==='WAITING_FOR_NAWAF').length,done:s.tasks.filter(t=>t.status==='COMPLETED').length,blocked:s.tasks.filter(t=>t.blockedReason&&open(t)).length,urgent:s.tasks.filter(t=>t.priority==='URGENT'&&open(t)).length};const p=priorities(s)[0];return {x,text:`عندك ${x.working} مهام تعمل الآن، ${x.waiting} قرارات تنتظرك، ${x.blocked} مهام متعثرة، و${x.done} مهام مكتملة.${p?' الأولوية الأعلى الآن: '+p.title+'.':''}`}}
function createTask(s,{title,details,kind='CUSTOM',projectId='',employeeId='',priority='NORMAL'}){const e=employeeId?s.employees.find(x=>x.id===employeeId):chooseEmployee(s,{title,details});const t={id:uid('t'),title,details:details||title,kind,projectId,employeeId:e?.id||'',priority,status:'READY',progress:0,createdAt:new Date().toISOString()};s.tasks.unshift(t);activity(s,`تم إنشاء مهمة: ${title}`);return t}
function runCompanyGoal(){const s=ensure(read()),projects=s.projects;modal('شغّل الشركة',`<form id="v15-goal-form" class="v15-form"><label>الهدف الكبير<textarea name="goal" rows="4" required placeholder="مثال: جهّز قدّها للإطلاق وتأكد أن الألعاب كلها تعمل"></textarea></label><label>المشروع<select name="projectId"><option value="">عام</option>${projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><button class="v15-primary" type="submit">شغّل الفريق كامل</button></form>`);$('#v15-goal-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),goal=String(f.get('goal')||'').trim(),projectId=String(f.get('projectId')||'');if(!goal)return;const q=ensure(read()),g={id:uid('g'),title:goal,projectId,status:'ACTIVE',createdAt:new Date().toISOString()};q.goals.unshift(g);createTask(q,{title:'خطة تنفيذ الهدف',details:`حلّل الهدف وقسّمه إلى خطوات قابلة للتنفيذ: ${goal}`,kind:'PLAN',projectId,priority:'HIGH'});createTask(q,{title:'بحث وتجميع السياق',details:`اجمع المعلومات والمتطلبات والمخاطر اللازمة لتحقيق: ${goal}`,kind:'RESEARCH',projectId,priority:'HIGH'});createTask(q,{title:'تنفيذ الهدف',details:goal,kind:'CUSTOM',projectId,priority:'URGENT'});const qa=q.employees.find(x=>/نورة|جود|quality/i.test((x.name||'')+' '+(x.role||'')));createTask(q,{title:'فحص جودة نهائي',details:`اختبر الناتج المرتبط بالهدف: ${goal}. سجّل الأخطاء ولا تعتبر المهمة ناجحة إذا بقي خلل جوهري.`,kind:'REVIEW',projectId,employeeId:qa?.id||'',priority:'HIGH'});activity(q,`تم تقسيم هدف الشركة إلى خطة تنفيذ: ${goal}`);write(q,'v15-company-goal');$('#v15-modal')?.classList.remove('show');toast('تم تقسيم الهدف وإرساله لمحرك التنفيذ');setTimeout(()=>{const z=ensure(read()),ready=z.tasks.filter(t=>t.status==='READY'&&t.projectId===projectId&&[goal,`حلّل الهدف وقسّمه إلى خطوات قابلة للتنفيذ: ${goal}`,`اجمع المعلومات والمتطلبات والمخاطر اللازمة لتحقيق: ${goal}`].some(x=>(t.details||'').includes(x)));ready.slice(0,3).forEach((t,i)=>setTimeout(()=>window.NawafAgents?.runTask?.(t.id).catch(()=>{}),250+i*450))},180)}}
function projectMemory(){const s=ensure(read());modal('ذاكرة المشاريع',`<div class="v15-stack">${s.projects.map(p=>`<button class="v15-memory-row" data-v15-memory="${esc(p.id)}"><span><b>${esc(p.name)}</b><small>${esc((s.projectMemory[p.id]||'لا توجد ملاحظات محفوظة').slice(0,110))}</small></span><i>فتح</i></button>`).join('')}</div>`,true);$$('[data-v15-memory]').forEach(b=>b.onclick=()=>memoryEditor(b.dataset.v15Memory))}
function memoryEditor(id){const s=ensure(read()),p=s.projects.find(x=>x.id===id);if(!p)return;modal(`ذاكرة ${p.name}`,`<form id="v15-memory-form" class="v15-form"><label>قرارات، قيود، مشاكل سابقة، وأشياء لا يجب تغييرها<textarea name="memory" rows="12" placeholder="اكتب ذاكرة المشروع هنا...">${esc(s.projectMemory[id]||'')}</textarea></label><button class="v15-primary" type="submit">حفظ الذاكرة</button></form>`,true);$('#v15-memory-form').onsubmit=e=>{e.preventDefault();const q=ensure(read());q.projectMemory[id]=String(new FormData(e.currentTarget).get('memory')||'').trim();activity(q,`تم تحديث ذاكرة مشروع ${p.name}`);write(q,'v15-memory');toast('تم حفظ ذاكرة المشروع')}}
function researchCenter(){const s=ensure(read()),items=s.tasks.filter(t=>t.kind==='RESEARCH'||/بحث|تحليل/.test(t.title)).slice(0,30),reports=s.reports.filter(r=>/بحث|تحليل|دراسة|تقرير/.test((r.title||'')+' '+(r.content||''))).slice(0,20);modal('مركز Research',`<div class="v15-two"><section><h3>مهام البحث</h3>${items.map(t=>`<div class="v15-listrow"><b>${esc(t.title)}</b><small>${esc(t.status)} • ${esc(t.priority||'NORMAL')}</small></div>`).join('')||'<p class="v15-empty">لا توجد مهام بحث.</p>'}</section><section><h3>المخرجات</h3>${reports.map(r=>`<div class="v15-listrow"><b>${esc(r.title)}</b><small>${esc(r.author||'AI')}</small></div>`).join('')||'<p class="v15-empty">لا توجد تقارير بحثية.</p>'}</section></div><button class="v15-primary" data-v15-new-research>+ بحث جديد</button>`,true);$('[data-v15-new-research]').onclick=()=>newResearch()}
function newResearch(){const s=ensure(read());modal('بحث جديد',`<form id="v15-research-form" class="v15-form"><label>موضوع البحث<textarea name="topic" rows="5" required></textarea></label><label>المشروع<select name="projectId"><option value="">عام</option>${s.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><button class="v15-primary">ابدأ البحث</button></form>`);$('#v15-research-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),q=ensure(read()),topic=String(f.get('topic')||'').trim();createTask(q,{title:`بحث: ${topic}`,details:`ابحث بعمق، قارن المصادر، استخرج الاستنتاجات والمخاطر، ثم أنشئ تقريرًا واضحًا: ${topic}`,kind:'RESEARCH',projectId:String(f.get('projectId')||''),priority:'HIGH'});write(q,'v15-research');$('#v15-modal')?.classList.remove('show');toast('تم إنشاء مهمة البحث')}}
function qaCenter(){const s=ensure(read()),qa=s.tasks.filter(t=>t.kind==='REVIEW'||/فحص|اختبار|جود|QA/i.test(t.title)).slice(0,30);modal('مركز الجودة QA',`<div class="v15-kpis"><div><b>${qa.filter(t=>active(t)).length}</b><span>تحت الفحص</span></div><div><b>${qa.filter(t=>t.status==='COMPLETED').length}</b><span>نجح</span></div><div><b>${qa.filter(t=>t.blockedReason).length}</b><span>يحتاج إصلاح</span></div></div><div class="v15-stack">${qa.map(t=>`<div class="v15-listrow"><b>${esc(t.title)}</b><small>${esc(t.status)}${t.blockedReason?' • '+esc(t.blockedReason):''}</small></div>`).join('')||'<p class="v15-empty">لا توجد جولات QA حتى الآن.</p>'}</div><button class="v15-primary" data-v15-qa-sweep>فحص كل المشاريع النشطة</button>`,true);$('[data-v15-qa-sweep]').onclick=qaSweep}
function qaSweep(){const s=ensure(read()),qa=s.employees.find(x=>/نورة|جود|quality|مراجع/i.test((x.name||'')+' '+(x.role||'')));for(const p of s.projects.filter(x=>x.status!=='PAUSED'))createTask(s,{title:`QA شامل — ${p.name}`,details:`افحص ${p.name} من البداية للنهاية: الروابط، الأزرار، الحالات، الجوال، الأخطاء الظاهرة، واستمرارية البيانات. أنشئ تقريرًا بالمشاكل الحقيقية فقط.`,kind:'REVIEW',projectId:p.id,employeeId:qa?.id||'',priority:'HIGH'});write(s,'v15-qa-sweep');$('#v15-modal')?.classList.remove('show');toast('تم إنشاء فحص QA للمشاريع النشطة')}
function meetingRoom(){const s=ensure(read());modal('غرفة اجتماعات AI',`<form id="v15-meeting-form" class="v15-form"><label>موضوع الاجتماع<textarea name="topic" rows="4" required placeholder="مثال: كيف نرفع جودة قدّها قبل الإطلاق؟"></textarea></label><label>المشروع<select name="projectId"><option value="">عام</option>${s.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><button class="v15-primary">ابدأ الاجتماع</button></form>`);$('#v15-meeting-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),q=ensure(read()),topic=String(f.get('topic')||'').trim(),projectId=String(f.get('projectId')||''),m={id:uid('m'),topic,projectId,createdAt:new Date().toISOString(),status:'OPEN'};q.meetings.unshift(m);q.employees.slice(0,4).forEach(emp=>createTask(q,{title:`رأي ${emp.name}: ${topic}`,details:`شارك برأيك من زاوية دورك الوظيفي حول: ${topic}. اذكر المخاطر والتوصية.`,kind:'ANALYZE',projectId,employeeId:emp.id,priority:'NORMAL'}));const boss=q.employees.find(x=>/سارة|مدير/i.test((x.name||'')+' '+(x.role||'')))||q.employees[0];createTask(q,{title:`قرار الاجتماع: ${topic}`,details:`راجع آراء الفريق حول ${topic} ثم لخّص نقاط الاتفاق والاختلاف واخرج بقرار تنفيذي واضح.`,kind:'REVIEW',projectId,employeeId:boss?.id||'',priority:'HIGH'});activity(q,`بدأ اجتماع AI: ${topic}`);write(q,'v15-meeting');$('#v15-modal')?.classList.remove('show');toast('بدأ الاجتماع وتم توزيع الأدوار')}}
function costCenter(){const s=ensure(read()),runs=s.tasks.filter(t=>t.lastRunAt||t.executionStartedAt).length,external=s.tasks.filter(t=>t.executionResult).length;modal('الاستهلاك والتكاليف',`<div class="v15-kpis"><div><b>${s.tasks.length}</b><span>إجمالي المهام</span></div><div><b>${runs}</b><span>تشغيلات مسجلة</span></div><div><b>${external}</b><span>تنفيذات مشاريع</span></div><div><b>0 ر.س</b><span>صرف مدفوع مسجل</span></div></div><div class="v15-note"><b>سياسة الصرف</b><p>NAWAF HQ لا يعتبر أي خدمة مدفوعة مصرحًا بها تلقائيًا. أي تكلفة مستقبلية يجب أن تمر بموافقتك. أرقام التوكنز/الفواتير الحقيقية لا تُعرض إلا إذا وفرتها الخدمة المتصلة؛ ما عندنا بيانات فواتير مزيفة.</p></div>`,true)}
function permissions(){const s=ensure(read());modal('الصلاحيات',`<div class="v15-stack">${s.employees.map(e=>{const p=e.permissions||{};return `<article class="v15-perm" data-emp="${esc(e.id)}"><header><b>${esc(e.name)}</b><small>${esc(e.role||'موظف AI')}</small></header>${[['tasks','تشغيل المهام'],['projects','إدارة المشاريع'],['code','تعديل الكود'],['external','أدوات خارجية'],['deploy','النشر']].map(([k,l])=>`<label><span>${l}</span><input type="checkbox" data-perm="${k}" ${p[k]!==false?'checked':''}></label>`).join('')}</article>`}).join('')}</div><button class="v15-primary" data-v15-save-perms>حفظ الصلاحيات</button>`,true);$('[data-v15-save-perms]').onclick=()=>{const q=ensure(read());$$('.v15-perm').forEach(card=>{const e=q.employees.find(x=>x.id===card.dataset.emp);if(!e)return;e.permissions=e.permissions||{};card.querySelectorAll('[data-perm]').forEach(i=>e.permissions[i.dataset.perm]=i.checked)});activity(q,'تم تحديث صلاحيات موظفي AI');write(q,'v15-permissions');toast('تم حفظ الصلاحيات')}}
function deployments(){const rows=[['NAWAF HQ',location.origin,'/api/health'],['مُعِين','https://mueen-islamic-app.vercel.app/',''],['قدّها','https://qaddha.vercel.app/','']];modal('مركز النشر',`<div class="v15-stack">${rows.map((r,i)=>`<article class="v15-deploy"><span><b>${esc(r[0])}</b><small>${esc(r[1])}</small></span><div>${i===0?'<button data-v15-health>فحص النظام</button>':''}<a href="${esc(r[1])}" target="_blank" rel="noopener">فتح</a></div></article>`).join('')}</div><div id="v15-health-result" class="v15-note"><p>حالة النشر تعتمد على الفحص الفعلي، وليست أرقامًا تجميلية.</p></div>`,true);$('[data-v15-health]')?.addEventListener('click',async()=>{const out=$('#v15-health-result');out.innerHTML='<p>جاري الفحص…</p>';try{const r=await fetch('/api/health',{cache:'no-store'}),d=await r.json();out.innerHTML=`<b>${r.ok&&d.ok?'النظام شغال ✓':'يوجد خلل'}</b><p>${esc(JSON.stringify(d))}</p>`}catch(e){out.innerHTML=`<b>تعذر الفحص</b><p>${esc(e.message)}</p>`}})}
function goals(){const s=ensure(read());modal('أهداف الشركة',`<div class="v15-stack">${s.goals.map(g=>{const ts=s.tasks.filter(t=>t.projectId===g.projectId||t.details?.includes(g.title)),done=ts.filter(t=>t.status==='COMPLETED').length,pct=ts.length?Math.round(done/ts.length*100):0;return `<article class="v15-goal"><span><b>${esc(g.title)}</b><small>${esc(g.status||'ACTIVE')} • ${pct}%</small></span><div class="v15-progress"><i style="width:${pct}%"></i></div></article>`}).join('')||'<p class="v15-empty">ما عندك أهداف مسجلة. استخدم زر «شغّل الشركة» لإضافة أول هدف.</p>'}</div>`,true)}
function worklog(){const s=ensure(read());modal('سجل عمل الموظفين',`<div class="v15-stack">${s.employees.map(e=>{const tasks=s.tasks.filter(t=>t.employeeId===e.id).slice(0,6);return `<article class="v15-worklog"><header><b>${esc(e.name)}</b><small>${esc(e.status||'READY')}</small></header>${tasks.map(t=>`<div><span>${esc(t.title)}</span><small>${esc(t.status)} • ${t.progress||0}%</small></div>`).join('')||'<p>لا توجد مهام.</p>'}</article>`}).join('')}</div>`,true)}
function decisionInbox(){if(window.NawafHQV13?.openCenter)return window.NawafHQV13.openCenter();const s=ensure(read()),w=s.tasks.filter(t=>t.status==='WAITING_FOR_NAWAF');modal('Inbox القرارات',w.map(t=>`<div class="v15-listrow"><b>${esc(t.title)}</b><small>${esc(t.blockedReason||'تحتاج قرارك')}</small></div>`).join('')||'<p class="v15-empty">لا توجد قرارات معلقة.</p>',true)}
function finance(){if(window.NawafFinance?.open)return window.NawafFinance.open();toast('المحلل المالي غير محمل')}
function render(){if(!$('.v8-main')||!$('[data-view="dashboard"]')?.classList.contains('active'))return;let root=$('.v15-os');if(!root){root=document.createElement('section');root.className='v15-os';const a=$('.v14-dashboard')||$('.v8-stats');a?.insertAdjacentElement('afterend',root)}if(!root)return;const s=ensure(read()),b=brief(s),p=priorities(s),c=cfg();root.innerHTML=`<div class="v15-command"><div><span>COMPANY OS</span><h2>مركز القيادة التنفيذي</h2><p>${esc(b.text)}</p></div><button class="v15-run" data-v15="run-company">▶ شغّل الشركة</button></div><div class="v15-strip"><button data-v15="decisions"><b>${b.x.waiting}</b><span>Inbox القرارات</span></button><button data-v15="worklog"><b>${s.tasks.filter(active).length}</b><span>العمل الحي</span></button><button data-v15="manager"><b>${p.length}</b><span>مدير المشاريع AI</span></button><button data-v15="goals"><b>${s.goals.length}</b><span>أهداف الشركة</span></button></div><div class="v15-tools">${[['brief','Morning Brief'],['research','Research'],['qa','QA'],['meeting','غرفة الاجتماعات'],['memory','ذاكرة المشاريع'],['finance','المحلل المالي'],['cost','الاستهلاك'],['deploy','Deployments'],['permissions','الصلاحيات']].map(([a,l])=>`<button data-v15="${a}">${l}</button>`).join('')}</div>${c.showPriority!==false?`<div class="v15-priority"><header><b>الترتيب الذكي</b><button data-v15="manager">إعادة الترتيب والإسناد</button></header>${p.slice(0,5).map((t,i)=>`<div><em>${i+1}</em><span><b>${esc(t.title)}</b><small>${esc(t.priority||'NORMAL')} • ${esc(t.status||'READY')}</small></span><strong>${Math.round(scoreTask(t))}</strong></div>`).join('')||'<p class="v15-empty">لا توجد مهام مفتوحة.</p>'}</div>`:''}`;root.querySelectorAll('[data-v15]').forEach(b=>b.onclick=()=>action(b.dataset.v15))}
function morning(){const s=ensure(read()),b=brief(s),top=priorities(s).slice(0,5);modal('Morning Brief',`<div class="v15-brief"><h3>${esc(b.text)}</h3><div class="v15-kpis"><div><b>${b.x.working}</b><span>يعمل الآن</span></div><div><b>${b.x.waiting}</b><span>قرار لك</span></div><div><b>${b.x.blocked}</b><span>متعثر</span></div><div><b>${b.x.done}</b><span>مكتمل</span></div></div><h4>أهم ما يحتاج انتباهك</h4>${top.map((t,i)=>`<div class="v15-listrow"><b>${i+1}. ${esc(t.title)}</b><small>${esc(t.blockedReason||t.status)}</small></div>`).join('')||'<p class="v15-empty">الوضع هادئ.</p>'}</div>`,true)}
function action(a){({brief:morning,research:researchCenter,qa:qaCenter,meeting:meetingRoom,memory:projectMemory,finance,cost:costCenter,deploy:deployments,permissions,decisions:decisionInbox,worklog,manager:managerRun,goals,'run-company':runCompanyGoal}[a]||(()=>{}))()}
let timer;function schedule(){clearTimeout(timer);timer=setTimeout(render,100)}function boot(){ensure(read());new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});window.addEventListener('nawaf:state-updated',schedule);setInterval(()=>!document.hidden&&render(),15000);render()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
window.NawafHQV15={render,managerRun,runCompanyGoal,qaSweep,researchCenter,meetingRoom,projectMemory,permissions,deployments,costCenter,morning};
})();